// Deterministic down-payment status: every answer is built from stored records. Never generated by the model.
export const AWAITING_SLIP = 'Awaiting manual verification slip.';

const PAYMENT_INTENT = /\b(down\s?payments?|dp|deposits?|bayad|nagbayad|nabayaran|naka-?bayad|payments?|gcash|maya|bpi|slips?|resibo|received|status)\b/i;
const FILLER = new Set([
  'ang', 'ng', 'nang', 'ni', 'si', 'sa', 'na', 'ba', 'po', 'ko', 'mo', 'nya', 'niya', 'yung', 'yong', 'may', 'ano', 'anong', 'magkano', 'how', 'much',
  'is', 'the', 'of', 'for', 'has', 'have', 'did', 'does', 'check', 'pa', 'ung', 'kay', 'kina', 'what', 'whats', "what's", 'my', 'our', 'their', 'pls', 'please',
]);

export function isPaymentStatusQuery(text: string) {
  return PAYMENT_INTENT.test(text);
}

// Returns the client/order reference in a payment question ("DP status Panasonic" -> "Panasonic"), or '' if none.
export function paymentQueryRef(text: string) {
  return text
    .split(/[\s?!.,]+/)
    .map((token) => token.trim())
    .filter((token) => token && !FILLER.has(token.toLowerCase()) && !PAYMENT_INTENT.test(token))
    .join(' ')
    .trim();
}

export type PaymentOrder = {
  order_number: string;
  client_name: string | null;
  deposit_amount: number;
  deposit_verification_id: string | null;
};

export type PaymentSlip = {
  expected_amount: number;
  detected_amount: number | null;
  reference: string | null;
  transaction_date: string | null;
  recipient: string | null;
  verified: boolean;
};

export type PaymentState = 'RECEIVED_VERIFIED' | 'RECEIVED_LEDGER' | 'PENDING_VERIFICATION' | 'NOT_YET_RECEIVED';

// Verified slip wins; a booked deposit ledger row (staff-confirmed) counts as received; a slip that is not yet verified is pending.
export function paymentState(order: PaymentOrder, slip: PaymentSlip | null, hasLedgerDeposit: boolean): PaymentState {
  if (slip?.verified) return 'RECEIVED_VERIFIED';
  if (hasLedgerDeposit) return 'RECEIVED_LEDGER';
  if (slip || order.deposit_verification_id) return 'PENDING_VERIFICATION';
  return 'NOT_YET_RECEIVED';
}

const STATE_LABEL: Record<PaymentState, string> = {
  RECEIVED_VERIFIED: 'RECEIVED ✅ (slip verified)',
  RECEIVED_LEDGER: 'RECEIVED ✅ (staff-confirmed, booked in ledger)',
  PENDING_VERIFICATION: 'PENDING ⏳ (slip on file, not yet verified)',
  NOT_YET_RECEIVED: 'NOT YET RECEIVED ❌',
};

const peso = (value: number) => `₱${Math.round(value).toLocaleString('en-PH')}`;

export function formatPaymentStatus(order: PaymentOrder, slip: PaymentSlip | null, hasLedgerDeposit: boolean): string {
  const state = paymentState(order, slip, hasLedgerDeposit);
  const lines = [
    `${order.client_name || 'Client'} · ${order.order_number}`,
    `Down payment: ${peso(Number(order.deposit_amount || 0))}`,
    `Status: ${STATE_LABEL[state]}`,
  ];
  if (slip) {
    lines.push(`Reference: ${slip.reference || 'none on slip'}`);
    if (slip.detected_amount != null) lines.push(`Detected amount: ${peso(Number(slip.detected_amount))}`);
    if (slip.transaction_date) lines.push(`Transaction date: ${slip.transaction_date}`);
    if (slip.recipient) lines.push(`Recipient / channel: ${slip.recipient}`);
  }
  if (state === 'NOT_YET_RECEIVED' || state === 'PENDING_VERIFICATION' || !slip?.reference) lines.push(AWAITING_SLIP);
  return lines.join('\n');
}
